void MainWindow::libraries(){LibraryManagerDialog dialog(this);Language::translateTree(&dialog);dialog.exec();}

bool MainWindow::startPageVisible()const{return workspace_->currentWidget()==startPage_;}
void MainWindow::showStartPage(){
    if(startPageVisible())return;
    stopSimulation();editorLayout_=saveState();
    for(auto* dock:findChildren<QDockWidget*>())dock->hide();
    for(auto* bar:findChildren<QToolBar*>())bar->hide();
    for(auto* menu:menuBar()->actions())if(menu->menu()){
        const auto text=Language::text(menu->text());
        if(text==Language::text("Bearbeiten")||text==Language::text("Ansicht"))menu->setEnabled(false);
    }
    workspace_->setCurrentWidget(startPage_);startPage_->refresh();
}
void MainWindow::showEditor(){
    if(!startPageVisible())return;
    workspace_->setCurrentWidget(canvas_);
    if(!editorLayout_.isEmpty())restoreState(editorLayout_);
    for(auto* menu:menuBar()->actions())menu->setEnabled(true);
    QTimer::singleShot(0,canvas_,&CircuitCanvas::fitCircuit);
}
void MainWindow::resetSimulation(){
    const bool restart=simulationActive();stopSimulation();runtimes_.clear();peripherals_.reset();i2cDevices_.reset();sensors_.reset();pixels_.reset();uart_.reset();interrupts_.reset();transient_.reset();analogTarget_=0;instruments_->reset();
    for(auto& [id,display]:displays_){(void)id;display.reset();}
    updateCircuit();canvas_->updateSimulation(circuitState_,displays_);renderDirty_=true;
    appendLog(Language::text("Simulation zurückgesetzt."));if(restart)startSimulation();
}

SavedProject MainWindow::snapshot(){syncBoardSketches();QMap<QString,SketchProject> sketches;for(const auto& part:circuit_.parts())if(part.kind==PartKind::Esp8266)sketches[QString::fromStdString(part.id)]=boardSketches_.value(QString::fromStdString(part.id));return {circuit_,currentSketch(),sketches,projectBundle_,executionMode_};}
void MainWindow::autosave(){if(!dirty())return;try{recovery_.save(snapshot(),projectFile_);}catch(const std::exception& e){appendLog(Language::text("Autospeichern fehlgeschlagen: ")+QString::fromUtf8(e.what()));}}
bool MainWindow::recoverProject(const QString& path){try{auto project=ProjectIO::load(path);loadBundle(project);stopSimulation();executionMode_=project.mode;updateExecutionMode();recovery_.clear();runtimes_.clear();displays_.clear();circuit_=std::move(project.circuit);canvas_->rebuild();canvas_->resetHistory();sketchBoard_=circuit_.boardId();boardSketches_=project.boardSketches;setSketch(boardSketches_.value(QString::fromStdString(sketchBoard_),project.sketch));projectFile_.clear();inputDirty_=true;updateCircuit();refreshTitle();showEditor();canvas_->fitCircuit();recovery_.save(snapshot(),{});if(path!=recovery_.path())ProjectRecovery::discard(path);appendLog(Language::text("Projekt wiederhergestellt. Bitte unter neuem Namen speichern."));return true;}catch(const std::exception& e){appendLog(QString::fromUtf8(e.what()));return false;}}
void MainWindow::recoveryDialog(){QDialog dialog(this);dialog.setObjectName("recoveryDialog");dialog.setWindowTitle(Language::text("Projekte wiederherstellen"));dialog.resize(650,350);auto* layout=new QVBoxLayout(&dialog);auto* explanation=new QLabel(Language::text("Automatische Sicherungen nach einem unerwarteten Ende. Geöffnete Sitzungen werden nicht angezeigt."));explanation->setWordWrap(true);layout->addWidget(explanation);auto* list=new QListWidget;layout->addWidget(list);const auto entries=ProjectRecovery::available();for(const auto& entry:entries){auto* item=new QListWidgetItem(entry.name+" · "+entry.modified.toLocalTime().toString("yyyy-MM-dd HH:mm")+"\n"+entry.source,list);item->setData(Qt::UserRole,entry.path);}list->setCurrentRow(0);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Open|QDialogButtonBox::Cancel);auto* discard=buttons->addButton(Language::text("Sicherung löschen"),QDialogButtonBox::DestructiveRole);layout->addWidget(buttons);connect(discard,&QPushButton::clicked,&dialog,[list]{if(auto* item=list->currentItem()){ProjectRecovery::discard(item->data(Qt::UserRole).toString());delete list->takeItem(list->row(item));}});connect(buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);if(dialog.exec()==QDialog::Accepted&&list->currentItem()&&maybeSave())recoverProject(list->currentItem()->data(Qt::UserRole).toString());}

void MainWindow::pauseSimulation(bool on){if(!simulationActive()){QSignalBlocker block(pause_);pause_->setChecked(false);return;}paused_=on;for(auto& [id,runtime]:runtimes_)runtime->interpreter.setPaused(on);if(on)sound_.stop();else updateCircuit();}
void MainWindow::stepSimulation(){if(!simulationActive())return;pause_->setChecked(true);if(analogRunning_){analogTarget_=transient_.now()+100;updateCircuit(true);}else for(auto& [id,runtime]:runtimes_)runtime->interpreter.stepOnce();}

void MainWindow::loadBundle(const SavedProject& project){auto directory=std::make_unique<QTemporaryDir>();if(!directory->isValid())throw std::runtime_error("Cannot create project library directory");auto roots=ProjectIO::extractLibraries(project.bundledLibraries,directory->path());projectBundle_=project.bundledLibraries;projectLibraries_=roots;bundledDirectory_=std::move(directory);}

void MainWindow::saveLocalAutomatically(){if(projectFile_.isEmpty()||!dirty()||!QSettings().value("localAutosave",true).toBool())return;try{ProjectIO::save(projectFile_,snapshot());recovery_.clear();sketchesDirty_=false;inputDirty_=false;canvas_->history()->setClean();for(int i=0;i<codeTabs_->count();++i)static_cast<CodeEditor*>(codeTabs_->widget(i))->document()->setModified(false);refreshTitle();statusBar()->showMessage(Language::text("Projekt automatisch gespeichert."),4000);}catch(const std::exception& e){appendLog(Language::text("Autospeichern fehlgeschlagen: ")+QString::fromUtf8(e.what()));}}

void MainWindow::checkLesson(){if(activeLesson_.isEmpty()||!simulationActive()||!circuitState_.errors.empty())return;bool goal=false;auto ledOn=[&]{for(const auto& [id,current]:circuitState_.ledCurrent)if(current>.001)return true;return false;};
if(activeLesson_=="led_blink")goal=ledOn();
else if(activeLesson_=="button_led"){bool pressed=false;for(const auto& p:circuit_.parts())if(p.kind==PartKind::Button)pressed|=p.pressed;goal=pressed&&ledOn();}
else if(activeLesson_=="analog_threshold"){for(const auto& p:circuit_.parts())if(p.kind==PartKind::AnalogSource)goal=p.value>.5&&std::abs(p.value-.75)>.01&&ledOn();}
else if(activeLesson_=="animation"){for(const auto& [id,display]:displays_)for(auto pixel:display.frame().pixels)goal|=pixel!=0;}
else if(activeLesson_=="analog_rc")goal=virtualTime()>=100000&&std::any_of(circuitState_.voltage.begin(),circuitState_.voltage.end(),[](const auto& v){return v.second&&*v.second>.1;});
else if(activeLesson_=="servo_sweep"){for(const auto& p:circuit_.parts())if(p.kind==PartKind::ServoMotor)goal=circuitState_.partValues.contains(p.id);}
else if(activeLesson_=="nfc_reader")goal=serial_->monitorText().mid(lessonSerialStart_).contains("Test UID:");
else if(activeLesson_=="nrf24_pair")goal=serial_->monitorText().mid(lessonSerialStart_).contains("RX: ThinkCad packet");
if(goal&&TutorialCourse::complete(activeLesson_)){statusBar()->showMessage(Language::text("Lektion abgeschlossen! Die nächste Übung ist freigeschaltet."),12000);for(auto* course:findChildren<TutorialCourse*>())course->refresh();}}

void MainWindow::updateExecutionMode(){if(!executionModeChoice_)return;const QSignalBlocker block(executionModeChoice_);executionModeChoice_->setCurrentIndex(executionMode_==ExecutionMode::Emulation?1:0);executionModeChoice_->setEnabled(!simulationActive());}
bool MainWindow::setExecutionMode(ExecutionMode mode){if(simulationActive())return false;if(executionMode_!=mode){executionMode_=mode;inputDirty_=true;updateExecutionMode();refreshTitle();}return true;}

void MainWindow::refreshModulePalette(){
    auto* group=findChild<QGroupBox*>("modulePaletteGroup");if(!group)return;auto* layout=qobject_cast<QVBoxLayout*>(group->layout());if(!layout)return;while(auto* item=layout->takeAt(0)){delete item->widget();delete item;}
    for(const auto& [id,model]:ModuleRegistry::definitions()){auto* button=new ComponentPaletteButton(QString::fromStdString(model.label));button->setObjectName("componentCard");button->setProperty("kind",int(PartKind::Module));button->setProperty("model",QString::fromStdString(id));button->setToolTip(QString::fromStdString(model.label)+" — "+Language::text("In die Arbeitsfläche ziehen"));layout->addWidget(button);}
    if(auto* search=findChild<QLineEdit*>("componentSearch"))QMetaObject::invokeMethod(search,"textChanged",Qt::DirectConnection,Q_ARG(QString,search->text()));
}

void MainWindow::startDebugging(){
    if(AppPaths::debugger().isEmpty()){appendLog(Language::text("Lokales GDB fehlt. Unter Einstellungen / Editor den Debugger auswählen."));return;}
    if(circuit_.boardId().empty()){appendLog(Language::text("Zum Debuggen wird ein Board benötigt."));return;}
    debuggingRequested_=true;startSimulation();if(auto* dock=findChild<QDockWidget*>("sourceDebuggerDock"))dock->show();
}
void MainWindow::showDebugLocation(const QString& board,const QString& file,int line){
    if(!simulationActive())return;
    pause_->setChecked(true);
    // The stopped board must still answer RPC when it is stepped; other boards
    // wait at their next virtual-time barrier until Continue is requested.
    auto found=runtimes_.find(board.toStdString());if(found!=runtimes_.end())found->second->interpreter.setPaused(false);
    if(circuit_.boardId()!=board.toStdString()){circuit_.setActiveBoard(board.toStdString());syncBoardSketches();updateInspector();}
    const auto wanted=QDir::fromNativeSeparators(file);
    for(int i=0;i<codeTabs_->count();++i){auto* editor=static_cast<CodeEditor*>(codeTabs_->widget(i));const auto name=editor->property("fileName").toString();const bool matches=wanted==name||wanted.endsWith('/'+name);editor->setExecutionLine(matches?line:0);if(matches)codeTabs_->setCurrentIndex(i);}
}
